INSERT INTO public.reference_solutions (question_id, language, code) SELECT q.id, 'python', 'import sys
data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
seen = set()
ans = ''NO''
for x in map(int, data[2:2 + n]):
    if k - x in seen:
        ans = ''YES''
        break
    seen.add(x)
print(ans)
' FROM q;

